const response = $input.first().json;
const produit = $('Get Produit Par ID').first().json;

let analyse;
try {
  const content = response.choices[0].message.content;
  analyse = JSON.parse(content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
} catch (e) {
  analyse = {
    type_produit: produit.categorie || 'produit',
    couleur_principale: 'inconnue',
    couleurs_secondaires: [],
    materiau: 'inconnu',
    caracteristiques: [],
    taille: 'standard',
    contexte_utilisation_suggere: 'bureau'
  };
}

return [{
  json: {
    produit_id: produit.id,
    reference: produit.reference,
    nom_produit: produit.nom_produit,
    categorie: produit.categorie,
    url_image: produit.url_image,
    analyse: analyse
  }
}];

