const input = $input.first().json;
const prevData = $('Parse Analyse').first().json;

let promptData;
try {
  const content = input.message?.content || (Array.isArray(input.content) ? input.content[0].text : input.content) || input.text || JSON.stringify(input);
  const cleanContent = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  promptData = JSON.parse(cleanContent);
} catch (e) {
  promptData = {
    prompt_flux_kontext: `Professional product photography of a ${prevData.analyse.type_produit} on a modern office desk with natural lighting, blurred background with subtle orange and green accent colors, clean minimalist style, high quality commercial photography, any visible text must be in French`,
    contexte_choisi: 'Bureau moderne',
    elements_arriere_plan: ['desk', 'natural light'],
    ambiance_lumiere: 'Natural daylight',
    justification: 'Contexte professionnel standard'
  };
}

return [{
  json: {
    ...prevData,
    prompt_flux_kontext: promptData.prompt_flux_kontext,
    contexte_choisi: promptData.contexte_choisi,
    elements_arriere_plan: promptData.elements_arriere_plan,
    ambiance_lumiere: promptData.ambiance_lumiere,
    justification_contexte: promptData.justification
  }
}];

const falResponse = $input.first().json;
const prevData = $('Parse Prompt Flux').first().json;

let imageUrl;
if (falResponse.images && falResponse.images.length > 0) {
  imageUrl = falResponse.images[0].url;
} else if (falResponse.image) {
  imageUrl = falResponse.image.url || falResponse.image;
} else if (falResponse.output) {
  imageUrl = falResponse.output;
} else {
  imageUrl = prevData.url_image;
}

return [{
  json: {
    ...prevData,
    image_transformee_url_temp: imageUrl,
    flux_kontext_success: imageUrl !== prevData.url_image
  }
}];

const cloudinaryResponse = $input.first().json;
const prevData = $('Parse Fal Response').first().json;

return [{
  json: {
    ...prevData,
    image_transformee_url: cloudinaryResponse.secure_url || cloudinaryResponse.url,
    cloudinary_public_id: cloudinaryResponse.public_id
  }
}];

